  radarConnected: ["A sensor is connected", "Hay un sensor conectado", "Ein Sensor ist angeschlossen", "Un capteur est connecté", "Un sensore è collegato", "センサーを接続している", "已连接传感器", "Está ligado um sensor"],
  state_reporting: ["reporting", "informando", "meldet", "en émission", "in funzione", "報告中", "正在上报", "a reportar"],
  state_no_data: ["no data: RX not connected, no power or the wrong pin", "sin datos: RX sin conectar, sin alimentación o pin equivocado", "keine Daten: RX nicht angeschlossen, keine Spannung oder falscher Pin", "pas de données : RX non connecté, pas d'alimentation ou mauvaise broche", "nessun dato: RX non collegato, senza alimentazione o pin sbagliato", "データなし：RX未接続、電源なし、またはピン違い", "无数据：RX未连接、无电源或引脚错误", "sem dados: RX não ligado, sem alimentação ou pino errado"],
  state_garbled: ["bytes but no valid frame: wrong baud rate, bad ground or another mode", "llegan bytes pero ninguna trama válida: velocidad errónea, masa mala u otro modo", "Bytes, aber kein gültiger Rahmen: falsche Baudrate, schlechte Masse oder anderer Modus", "des octets mais aucune trame valide : mauvaise vitesse, mauvaise masse ou autre mode", "arrivano byte ma nessun frame valido: baud errato, massa cattiva o altra modalità", "バイトは届くが有効なフレームなし：ボーレート、GND不良、または別モード", "有字节但没有有效帧：波特率错误、接地不良或其他模式", "há bytes mas nenhuma trama válida: velocidade errada, má massa ou outro modo"],
  state_silent: ["it was reporting and stopped", "informaba y se ha detenido", "meldete und hat aufgehört", "émettait et s'est arrêté", "riportava e si è fermato", "報告していたが停止", "曾在上报，现已停止", "estava a reportar e parou"],
