  e_not_ant: ["This port is not reading an ANT-BMS.", "Este puerto no lee una ANT-BMS.", "Dieser Port liest kein ANT-BMS.", "Ce port ne lit pas de BMS ANT.", "Questa porta non legge un ANT-BMS.", "このポートは ANT-BMS を読んでいません。", "此端口没有读取 ANT-BMS。", "Esta porta não está a ler um ANT-BMS."],
  e_protocol_unknown: ["The BMS has not answered yet: wait for its first reading.", "La BMS aún no ha respondido: espera a su primera lectura.", "Das BMS hat noch nicht geantwortet: warten Sie auf seine erste Messung.", "Le BMS n'a pas encore répondu : attendez sa première mesure.", "Il BMS non ha ancora risposto: aspetta la sua prima lettura.", "BMS がまだ応答していません。最初の読み取りをお待ちください。", "BMS 尚未应答：请等待它的第一次读数。", "O BMS ainda não respondeu: espere pela sua primeira leitura."],
  e_old_protocol: ["This BMS speaks the older protocol, which has no settings request here.", "Esta BMS habla el protocolo antiguo, que aquí no tiene petición de ajustes.", "Dieses BMS spricht das ältere Protokoll, für das es hier keine Einstellungsanfrage gibt.", "Ce BMS parle l'ancien protocole, qui n'a pas ici de requête de réglages.", "Questo BMS parla il protocollo vecchio, che qui non ha una richiesta di impostazioni.", "この BMS は古いプロトコルで、ここでは設定の要求はありません。", "此 BMS 使用旧协议，此处没有设置请求。", "Este BMS fala o protocolo mais antigo, que aqui não tem pedido de definições."],
  e_bms_busy: ["The settings are already being read.", "Ya se están leyendo los ajustes.", "Die Einstellungen werden bereits gelesen.", "Les réglages sont déjà en cours de lecture.", "Le impostazioni sono già in lettura.", "設定はすでに読み取り中です。", "设置已在读取中。", "As definições já estão a ser lidas."],
  e_silent: ["The BMS does not answer the requests (check the wiring, the 3.3 V supply and the speed).", "La BMS no responde a las peticiones (revisa el cableado, la alimentación de 3,3 V y la velocidad).", "Das BMS antwortet nicht auf die Anfragen (Verdrahtung, 3,3-V-Versorgung und Geschwindigkeit prüfen).", "Le BMS ne répond pas aux requêtes (vérifiez le câblage, l'alimentation 3,3 V et la vitesse).", "Il BMS non risponde alle richieste (controlla cablaggio, alimentazione a 3,3 V e velocità).", "BMS が要求に応答しません（配線、3.3 V 電源、速度を確認してください）。", "BMS 不应答请求（请检查接线、3.3 V 供电和速度）。", "O BMS não responde aos pedidos (verifique a ligação, a alimentação de 3,3 V e a velocidade)."],
  pn_boot: ["BOOT button", "botón BOOT", "BOOT-Taste", "bouton BOOT", "pulsante BOOT", "BOOT ボタン", "BOOT 按键", "botão BOOT"],
  pn_usb_serial: ["the USB-serial socket's pin", "pin del conector USB-serie", "Pin der USB-Seriell-Buchse", "broche de la prise USB-série", "pin della presa USB-seriale", "USB シリアル端子のピン", "USB 串口接口的引脚", "o pino da ficha USB-série"],
  pn_led: ["the RGB LED's pin", "pin del LED RGB", "Pin der RGB-LED", "broche de la LED RVB", "pin del LED RGB", "RGB LED のピン", "RGB LED 的引脚", "o pino do LED RGB"],
  p_too_fast_for_emulated: ["an emulated port only keeps up to 19200 baud", "un puerto emulado solo aguanta hasta 19200 baudios", "ein emulierter Port hält nur bis 19200 Baud", "un port émulé ne tient que jusqu'à 19200 bauds", "una porta emulata regge solo fino a 19200 baud", "エミュレートされたポートは 19200 ボーまでです", "模拟端口最高只支持 19200 波特", "uma porta emulada só aguenta até 19200 baud"],
  e_invalid_port: ["There is no such port.", "No existe ese puerto.", "Diesen Port gibt es nicht.", "Ce port n'existe pas.", "Questa porta non esiste.", "そのポートはありません。", "没有该端口。", "Essa porta não existe."],
